package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.entity.entities.player.hud.CustomUIHud;import com.hypixel.hytale.server.core.modules.entity.component.TransformComponent;import com.hypixel.hytale.server.core.ui.builder.UICommandBuilder;import com.hypixel.hytale.server.core.universe.PlayerRef;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import com.hypixel.hytale.server.core.inventory.ItemStack;import dev.astralreach.core.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
final class FieldService{
 record Target(String world,RocketRegistry.Cell at,String rescue,String title){}
 private static final Map<UUID,Target>targets=new ConcurrentHashMap<>();
 static FieldJournal journal(Store<EntityStore>s,Ref<EntityStore>r){var j=s.getComponent(r,AstralReachPlugin.journalType);if(j==null){j=new FieldJournal();s.putComponent(r,AstralReachPlugin.journalType,j);}j.reconcilePerks();BlueprintService.sync(s,r,j);return j;}
 static boolean moon(Store<EntityStore>s){return s.getExternalData().getWorld().getName().equals("AstralLune");}
 static LunarExpedition.Site nearest(Store<EntityStore>s,Ref<EntityStore>r){if(!moon(s))return new LunarExpedition.Site(91023,0,145);var t=s.getComponent(r,TransformComponent.getComponentType()).getPosition();return LunarExpedition.nearby((int)s.getExternalData().getWorld().getWorldConfig().getSeed(),(int)t.x,(int)t.z);}
 static LunarExpedition.Site site(Store<EntityStore>s,Ref<EntityStore>r){var j=journal(s,r);String selected=j.selectedSite.isEmpty()?j.discovered.stream().sorted().findFirst().orElse(""):j.selectedSite;if(!selected.isEmpty()){var parts=selected.split(":");return new LunarExpedition.Site(Integer.parseInt(parts[0]),Integer.parseInt(parts[1]),Integer.parseInt(parts[2]));}return nearest(s,r);}
 static RocketRegistry.Cell cell(LunarExpedition.Point p){return new RocketRegistry.Cell(p.x(),p.y(),p.z());}
 static String claimKey(LunarExpedition.Site site,int archive){return site.id()+"/"+archive;}
 static void inspect(Store<EntityStore>s,Ref<EntityStore>r,RocketRegistry.Cell at,LunarExpedition.Site site){if(!moon(s)||at==null||!RocketService.near(s,r,at))return;String id=NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at));var relay=site.relay();boolean source=id.equals("AR_DamagedRelay")&&at.equals(new RocketRegistry.Cell(relay.x(),relay.y()+1,relay.z()));boolean archive=id.equals("AR_ResearchArchive")&&(at.equals(cell(site.archive(0)))||at.equals(cell(site.archive(1))));if(source||archive){var j=journal(s,r);j.discovered.add(site.id());j.selectedSite=site.id();}}
 static int recoverable(Store<EntityStore>s,Ref<EntityStore>r,LunarExpedition.Site site){if(!moon(s))return -1;int fallback=-1;for(int i=0;i<2;i++){var at=cell(site.archive(i));if(RocketService.near(s,r,at)&&NativeBlocks.base(NativeBlocks.get(s.getExternalData().getWorld(),at)).equals("AR_ResearchArchive")){fallback=i;if(!journal(s,r).claimed.contains(claimKey(site,i)))return i;}}return fallback;}
 static void recover(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,LunarExpedition.Site site){int index=recoverable(s,r,site);if(index<0)throw new IllegalArgumentException("Stand beside an original archive inside the research shelter.");var j=journal(s,r);String key=claimKey(site,index);if(j.claimed.contains(key))throw new IllegalArgumentException("You already recovered this archive. Follow the other terminal or explore a new site.");var inv=s.getComponent(r,Player.getComponentType()).getInventory().getCombinedStorageHotbarBackpack();var rewards=LunarExpedition.reward(index).entrySet().stream().map(e->new ItemStack(e.getKey(),e.getValue())).toList();if(!YardInventory.refund(inv,rewards))throw new IllegalArgumentException("Make room for all recovered salvage; the archive remains available.");j.discovered.add(site.id());j.claimed.add(key);boolean unlocked=j.reconcilePerks();if(unlocked)AstralReachPlugin.message(p,"Permanent expedition reward unlocked: "+ExpeditionPerks.FUEL_TITLE+" · 5% less rocket fuel on future launches. Repeated copies do not stack this perk.");LunarEnvironment.interior(s,r,p,unlocked?"AR_Expedition_Perk":"AR_rescue_radio");AstralReachPlugin.message(p,index==0?"Survey archive recovered: titanium samples and hull salvage. The second terminal contains the team's final record.":"Final record recovered: the crew evacuated through the southern skylight. Their flight computer and frame plates are yours. The shelter has no breathable air.");}
 static void track(PlayerRef p,RescueService.Signal signal){if(!signal.allows(p.getUuid())||!signal.active(System.currentTimeMillis()))throw new IllegalArgumentException("This rescue signal is no longer available.");targets.put(p.getUuid(),new Target(signal.world(),signal.at(),signal.key(),signal.name()+" · rescue beacon"));}
 static void track(PlayerRef p,LunarExpedition.Point point,String title){targets.put(p.getUuid(),new Target("AstralLune",cell(point),null,title));}
 static void clear(){targets.clear();}
 static void stop(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){targets.remove(p.getUuid());s.getComponent(r,Player.getComponentType()).getHudManager().removeCustomHud(p,Hud.KEY);}
 static void tick(Store<EntityStore>s){var w=s.getExternalData().getWorld();for(var p:w.getPlayerRefs()){var r=p.getReference();if(r==null||!r.isValid()||r.getStore()!=s)continue;var player=s.getComponent(r,Player.getComponentType());if(player==null)continue;var target=targets.get(p.getUuid());if(target!=null&&target.rescue()!=null){var signal=RescueService.find(target.rescue(),p.getUuid());if(signal==null||!signal.active(System.currentTimeMillis())){stop(s,r,p);AstralReachPlugin.message(p,"Rescue signal lost, expired or access revoked.");target=null;}}
  if(target==null){if(player.getHudManager().getCustomHud(Hud.KEY)!=null)player.getHudManager().removeCustomHud(p,Hud.KEY);continue;}
  String detail;if(!target.world().equals(w.getName()))detail="Travel to "+(target.world().equals("AstralLune")?"Lune":target.world().equals("AstralOrbit")?"Orbis orbit":"Orbis")+" using your normal paid route";else{var pos=s.getComponent(r,TransformComponent.getComponentType()).getPosition();double dx=target.at().x()+.5-pos.x,dz=target.at().z()+.5-pos.z;double bearing=(Math.toDegrees(Math.atan2(dx,-dz))+360)%360;detail=StationPass.compass(bearing)+" · "+Math.round(Math.hypot(dx,dz))+"m · height "+Math.round(target.at().y()-pos.y)+"m";}
  var existing=player.getHudManager().getCustomHud(Hud.KEY);Hud hud;if(existing instanceof Hud h)hud=h;else{hud=new Hud(p);player.getHudManager().addCustomHud(p,hud);}hud.show(target.title(),detail);
 }targets.keySet().removeIf(id->com.hypixel.hytale.server.core.universe.Universe.get().getPlayer(id)==null);}
 private static final class Hud extends CustomUIHud{static final String KEY="AstralReach.Field";private String last="";Hud(PlayerRef p){super(p,KEY,11);}@Override protected void build(UICommandBuilder c){c.append("Pages/AstralReach/FieldHud.ui");}void show(String title,String detail){if((title+detail).equals(last))return;last=title+detail;var c=new UICommandBuilder();c.set("#Title.Text",title);c.set("#Direction.Text",detail);update(false,c);}}
 private FieldService(){}
}
